{"path": "durations.py", "content": "import re

_PART = re.compile(r'([0-9]+)([hms])')
_SECONDS = {'h': 3600, 'm': 60, 's': 1}
_ORDER = 'hms'


def parse_duration(text):
    """See SPEC.md."""
    if not isinstance(text, str):
        raise ValueError('duration must be a string')
    pos = 0
    last = -1
    total = 0
    found = False
    while pos < len(text):
        if found:
            # Spaces are allowed only between parts.
            while pos < len(text) and text[pos] == ' ':
                pos += 1
            if pos == len(text):
                raise ValueError(f'invalid duration: {text!r}')
        m = _PART.match(text, pos)
        if not m:
            raise ValueError(f'invalid duration: {text!r}')
        index = _ORDER.index(m.group(2))
        if index <= last:
            raise ValueError(f'repeated or out-of-order unit in {text!r}')
        last = index
        total += int(m.group(1)) * _SECONDS[m.group(2)]
        pos = m.end()
        found = True
    if not found:
        raise ValueError('empty duration')
    return total
